{
  "judgments": [
    {
      "proposal_id": "P0000",
      "source_refs": [
        "F005"
      ],
      "rationale": "In paragraph (a)(3), the text specifically states that persons pushing off or mooring a seaplane or float-equipped rotorcraft at a dock during surface movement are excepted from the preceding seating and safety belt requirements. Connecting exemption C0003 as an exception qualifying baseline requirement C0002 directly reflects this express exception.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0001",
      "source_refs": [
        "F003:F005",
        "F024"
      ],
      "rationale": "Paragraph (b) provides that unless otherwise stated, § 91.107 does not apply to operations conducted under part 121, 125, or 135 of 14 CFR chapter I. Establishing qualification links between this general exemption (C0015) and the section's core baseline obligations (C0000, C0001, and C0002) is fully supported by the text.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0002",
      "source_refs": [
        "F005",
        "F024"
      ],
      "rationale": "Paragraph (b) expressly states that paragraph (a)(3) does not apply to persons subject to § 91.105. Because claim C0002 represents the baseline occupant seating and restraint mandate of paragraph (a)(3), linking exemption C0016 to qualify C0002 as an exception is directly supported by the source.",
      "verdict": "supported"
    }
  ]
}
